function provisionBase(){const p=G.player.pos.clone(),[cx,cz]=worldToCell(p),s={id:1,r:SITE_R,core:[cx,cz],corePos:tilePoint(cx,cz),coreMax:160,coreHp:160,gates:[],cells:[],status:'secured',wave:5,group:new THREE.Group(),wobble:{},routes:[],circular:true};for(let x=Math.max(0,cx-s.r);x<=Math.min(WORLD-1,cx+s.r);x++)for(let z=Math.max(0,cz-s.r);z<=Math.min(WORLD-1,cz+s.r);z++)if(Math.hypot(x-cx,z-cz)<=s.r){s.cells.push([x,z]);G.cells[x][z].site=1;}G.cells[cx][cz].type='core';G.sites.push(s);restoreSiteVisuals(s);createClaimNodes(s);rebuildCollision();const arrival=gateArrival(s);if(arrival)G.player.pos.copy(arrival);const money=G.gold,stock={logs:economy().logs,stone:economy().stone,ore:economy().ore};G.gold=99999;Object.assign(economy(),{logs:9999,stone:9999,ore:9999});baseProvisioning=true;
 try{for(const id of ['house','arrow','arrow']){const b=BUILDS.find(b=>b.id===id);let made=false;for(let ring=2;ring<10&&!made;ring++)for(let i=0;i<24&&!made;i++){const point=s.corePos.clone().add(V3(Math.cos(i*Math.PI/12)*ring*CELL,0,Math.sin(i*Math.PI/12)*ring*CELL));point.y=heightAt(point.x,point.z);if(!placementReason(b,point)&&Math.abs(point.y-G.player.pos.y)<.5&&walkSegment(G.player.pos,point,.27,'nav')){const n=G.towers.length;place(b,...worldToCell(point),point);made=G.towers.length>n;}}}}finally{baseProvisioning=false;G.gold=money;Object.assign(economy(),stock);}for(const role of ['laborer','laborer','knight','ranger'])addResident(s,role);G.phase='explore';G.site=null;G.playerMesh.position.copy(G.player.pos);}
