function closestInteraction(){const items=interactables().filter(i=>!['hostileGate','camp'].includes(i.kind));for(const d of colony().discoveries)if(!d.claimed&&d.pos.distanceTo(G.player.pos)<8)items.push({kind:'discovery',o:d,title:d.name});if(G.view!=='first')return items.sort((a,b)=>a.o.pos.distanceToSquared(G.player.pos)-b.o.pos.distanceToSquared(G.player.pos))[0]||null;const direction=camera.getWorldDirection(V3()),ray=new THREE.Ray(camera.position,direction),obstacle=projectileObstacle(camera.position,camera.position.clone().addScaledVector(direction,8));let best=null,dist=Infinity;for(const item of items){const p=item.o.pos.clone().add(V3(0,item.kind==='resource'?.8:1,0)),radius=item.kind==='tower'?buildRadius(item.o.b):item.kind==='portal'?1.6:item.kind==='resource'?Math.max(.6,item.o.radius||1):.8,hit=ray.intersectSphere(new THREE.Sphere(p,radius),V3());if(!hit)continue;const distance=hit.distanceTo(camera.position);if(obstacle&&distance>obstacle.distanceTo(camera.position)+.8)continue;if(distance<dist){best=item;dist=distance;}}return best;}
