 if(kind==='enemy'){info=Math.ceil(o.hp)+'/'+Math.ceil(o.maxHp)+' health';if(G.view!=='first')action('Select target',()=>{chooseTarget(o);closeInteraction();});if(o===livingTarget())action('Lock target',()=>{G.targetLocked=true;closeInteraction();});}
