function renderBuildCatalog(){if(!document.getElementById('buildCatalog')||!G)return;const category=colony().category||'Defenses',query=$('buildSearch').value.toLowerCase(),signature=[category,query,G.gold,economy().logs,economy().stone,economy().ore,G.selected,G.towers.length].join('/');if($('buildCatalog').dataset.signature===signature)return;$('buildCatalog').dataset.signature=signature;const tabs=$('buildCategories');tabs.innerHTML='';for(const name of ['Defenses','Housing','Training','Production','Portals']){const button=document.createElement('button');button.textContent=name;button.className=name===category?'selected':'';button.onclick=()=>{colony().category=name;renderBuildCatalog();};tabs.appendChild(button);}$('buildCatalog').innerHTML='';BUILDS.forEach((b,index)=>{if(b.retired||buildCategory(b)!==category||query&&!b.name.toLowerCase().includes(query))return;const button=document.createElement('button'),cost=b.core?'1 portal kit':buildCost(b)+' gold · '+recipeText(DEFENSE_RECIPES[b.id]||{});button.className='build-card'+(index===G.selected?' selected':'');const title=document.createElement('strong');title.textContent=b.name;const price=document.createElement('span');price.textContent=cost;const detail=document.createElement('small');detail.textContent=b.core?'Instant portal · 6m ward · five defense waves':(b.description||'Laborer-built defense. Place freely while keeping enemy routes open.')+' · '+(b.work||(b.wall?10:18))+' labor seconds';button.append(title,price,detail);button.onclick=()=>{G.selected=index;updateHud();renderBuildCatalog();};$('buildCatalog').appendChild(button);});}
function showSettlementLedger(){G.uiCursor=true;document.exitPointerLock?.();const panel=$('settlementPanel');panel.classList.remove('hidden');panel.innerHTML='<header><h2>Settlement ledger</h2><button id="ledgerClose">Close</button></header><p>Homes recruit. Laborers build and gather. Use E beside a structure to manage it.</p><div class="ledgerResearch"><button id="researchTools">Improve tools</button><button id="researchDefense">Improve defenses</button></div><div id="ledgerContent"></div>';$('researchTools').onclick=()=>{upgradeEconomy('harvestLevel');renderLedger();};$('researchDefense').onclick=()=>{upgradeEconomy('defenseLevel');renderLedger();};$('ledgerClose').onclick=()=>{panel.classList.add('hidden');G.uiCursor=false;captureFirstPerson();};renderLedger();}
