function restoreDiscoveries(){for(const d of colony().discoveries){if(d.mesh)continue;const group=new THREE.Group(),mat=new THREE.MeshStandardMaterial({color:d.kind==='spring'?0x79cbd1:d.kind==='star'?0xd9aa65:0x8f9b91,emissive:d.kind==='spring'?0x245c68:d.kind==='star'?0x8c511b:0x273a35,emissiveIntensity:.5,roughness:.5});const stone=new THREE.Mesh(d.kind==='spring'?new THREE.CylinderGeometry(1.1,1.3,.3,16):new THREE.OctahedronGeometry(d.kind==='star'?.8:1.1,0),mat);stone.position.y=d.kind==='spring'?.12:1;group.add(stone);if(d.kind==='relic')for(let i=0;i<5;i++){const pillar=new THREE.Mesh(new THREE.BoxGeometry(.35,1.5+(i%2)*.5,.35),new THREE.MeshStandardMaterial({color:0x777e76,roughness:1}));pillar.position.set(Math.cos(i*1.256)*2,.75,Math.sin(i*1.256)*2);group.add(pillar);}group.position.copy(d.pos);G.world.add(group);d.mesh=group;if(d.kind==='star'){const beam=new THREE.Mesh(new THREE.CylinderGeometry(.06,.3,16,8),new THREE.MeshBasicMaterial({color:0xffc779,transparent:true,opacity:.32,depthWrite:false}));beam.position.y=8;group.add(beam);}}}
