applyHarvestedNodes=function(){const e=economy(),bodies=new Map((G.generatedBodies||[]).map(b=>[Math.round(b.x*100)+','+Math.round(b.z*100),b]));let changed=false;for(const n of e.nodes){if(n.cache)continue;const b=bodies.get(n.id);if(!b)continue;if(n.remaining<=0){n.respawnAt??=G.time+300;n.capacity??=n.kind==='logs'?24:32;b.regrowMatrices??=(b.draw||[]).map(part=>{const m=new THREE.Matrix4();part.mesh.getMatrixAt(part.index,m);return m;});}if(n.respawnAt&&G.time>=n.respawnAt){n.remaining=n.capacity||24;n.respawnAt=null;b.depleted=false;(b.draw||[]).forEach((part,i)=>{if(b.regrowMatrices?.[i]){part.mesh.setMatrixAt(part.index,b.regrowMatrices[i]);part.mesh.instanceMatrix.needsUpdate=true;}});changed=true;}}naturalHarvest();if(changed){rebuildCollision();if(G.site)refreshRoutes();}};
function terrainTexture(kind){const size=128,data=new Uint8Array(size*size*4),noise=makeNoise(hashStr('frontier/'+kind)),rng=mulberry32(hashStr(kind));for(let y=0;y<size;y++)for(let x=0;x<size;x++){const n=noise(x/15,y/15)*.45+noise(x/4,y/4)*.25+rng()*.3,grain=kind==='rock'?.65+n*.4-Math.pow(Math.abs(Math.sin(y*.19+noise(x/20,y/20)*5)),18)*.15:.65+n*.42;const i=(y*size+x)*4;data[i]=Math.min(255,255*grain);data[i+1]=Math.min(255,255*grain);data[i+2]=Math.min(255,255*grain);data[i+3]=255;}const texture=new THREE.DataTexture(new THREE.Uint8BufferAttribute(data,4).array,size,size);texture.wrapS=texture.wrapT=THREE.RepeatWrapping;texture.magFilter=THREE.LinearFilter;texture.minFilter=THREE.LinearMipmapLinearFilter;texture.generateMipmaps=true;texture.needsUpdate=true;return texture;}
const oldTexturedTerrain=buildTerrainMesh;
buildTerrainMesh=function(){const result=oldTexturedTerrain(),mesh=result?.isMesh?result:G.terrain;if(!mesh?.geometry)return result;const geometry=mesh.geometry,positions=geometry.attributes.position,normal=geometry.attributes.normal,uv=new Float32Array(positions.count*2),colors=new Float32Array(positions.count*3),noise=makeNoise(hashStr(G.seed+'biome'));geometry.clearGroups();const groundIndices=[],cliffIndices=[];for(let i=0;i<positions.count;i++){const x=positions.getX(i),y=positions.getY(i),z=positions.getZ(i),up=Math.abs(normal?.getY(i)||0)>.65;uv[i*2]=(up?x:Math.abs(normal?.getX(i)||0)>.5?z:x)*.55;uv[i*2+1]=(up?z:y)*.55;const mix=noise(x/25,z/25),color=up?new THREE.Color(0x61794b).lerp(new THREE.Color(0x9d9770),mix*.65):new THREE.Color(0x92928a).lerp(new THREE.Color(0x6a746f),mix);colors.set([color.r,color.g,color.b],i*3);if(i%3===0)(up?groundIndices:cliffIndices).push(i,i+1,i+2);}geometry.setIndex([...groundIndices,...cliffIndices]);geometry.addGroup(0,groundIndices.length,0);geometry.addGroup(groundIndices.length,cliffIndices.length,1);geometry.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));geometry.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));const grass=terrainTexture('grass'),rock=terrainTexture('rock');mesh.material=[new THREE.MeshStandardMaterial({map:grass,bumpMap:grass,bumpScale:.1,vertexColors:true,side:THREE.DoubleSide,roughness:1}),new THREE.MeshStandardMaterial({map:rock,bumpMap:rock,bumpScale:.18,vertexColors:true,side:THREE.DoubleSide,roughness:.96})];return result;};
const livingWorldMeshes=buildWorldMeshes;
buildWorldMeshes=function(){G.lairs=[];livingWorldMeshes();const bark=terrainTexture('bark');const mapped=new Set();for(const b of G.generatedBodies||[])for(const part of b.draw||[]){const mesh=part.mesh;if(mapped.has(mesh))continue;mapped.add(mesh);if(mesh.material?.isMeshStandardMaterial){mesh.material.map=bark;mesh.material.bumpMap=bark;mesh.material.bumpScale=.07;mesh.material.needsUpdate=true;}}};
function animateWilderness(dt){const c=colony();c.day=(c.day||0)+dt;c.eventClock-=dt;if(c.eventClock<=0){c.eventClock=100+G.rng()*70;const p=randomWildPoint(true);if(p){const d={id:'star-'+Math.floor(G.time),kind:'star',pos:p,name:'Fallen star',description:'A shard of portal magic draws prowling creatures. Recover it for a portal kit, gold and experience.',claimed:false};c.discoveries.push(d);restoreDiscoveries();rebuildCollision();for(let i=0;i<5;i++){const q=p.clone().add(V3(Math.cos(i*1.256)*5,0,Math.sin(i*1.256)*5));q.y=heightAt(q.x,q.z);wildernessSpawn(q,i===0?'brute':'grunt');}settlementNotice('A star has fallen '+Math.round(p.distanceTo(G.player.pos))+'m away. Look for the amber beacon.');}}
 for(const d of c.discoveries){if(!d.mesh)continue;if(d.kind==='star'){d.mesh.rotation.y+=dt*.4;d.mesh.children[0].position.y=1+Math.sin(G.time*2)*.18;}d.mesh.children[0].material.emissiveIntensity=d.claimed?.08:.45+Math.sin(G.time+d.pos.x)*.15;}
 if(!G.birds){G.birds=new THREE.Group();const mat=new THREE.MeshBasicMaterial({color:0x344449});for(let i=0;i<9;i++){const bird=new THREE.Mesh(new THREE.ConeGeometry(.3,.8,3),mat);bird.rotation.z=Math.PI/2;G.birds.add(bird);}G.world.add(G.birds);}G.birds.children.forEach((bird,i)=>{const a=G.time*.09+i*.18;bird.position.set(G.player.pos.x+Math.cos(a)*25,G.player.pos.y+17+Math.sin(a*2+i)*2,G.player.pos.z+Math.sin(a)*25);bird.rotation.y=-a;bird.scale.y=.7+Math.sin(G.time*5+i)*.3;});sun.intensity=.85+Math.sin(c.day/150)*.18;
}
const settlementPlayer=updatePlayer;
updatePlayer=function(dt){settlementPlayer(dt);animateWilderness(dt);};
// Defense waves use reachable wilderness approaches, never a protected spawn point.
const wardedSpawn=spawnEnemy;
spawnEnemy=function(type,gate,scale){if(gate!=null&&G.site){let p=G.site.gatePos[gate];if(!p||noSpawnAt(p)){p=null;for(let i=0;i<24&&!p;i++){const angle=i*Math.PI/12,r=G.site.r*CELL+8+Math.floor(i/12)*10,q=G.site.corePos.clone().add(V3(Math.cos(angle)*r,0,Math.sin(angle)*r));q.y=heightAt(q.x,q.z);if(inGrid(...worldToCell(q))&&!noSpawnAt(q)&&!blockedAt(q.x,q.z,q.y,1.26,1.6,'nav')&&gridPlan(q,G.site.corePos,1.26))p=q;}if(!p){settlementNotice('This approach is protected; no enemy can materialize here.');return null;}}const e=wardedSpawn(type,null,scale);e.pos.copy(p);e.cell=worldToCell(p);e.routeId=gate;e.routeCursor=0;e.mesh.position.copy(p);return e;}return wardedSpawn(type,gate,scale);};

const plannedPreview=previewWall;
previewWall=function(){plannedPreview();if(G?.buildMode){const b=BUILDS[G.selected];$('tip').textContent=b.core?'Portal gate · instant ward · requires one portal kit':b.name+' blueprint · '+buildCost(b)+' gold · '+recipeText(DEFENSE_RECIPES[b.id]||{})+' · laborers build it';}};

const discoveryMinimap=drawMinimap;
drawMinimap=function(){discoveryMinimap();const ctx=$('mini').getContext('2d'),scale=160/WORLD;for(const d of colony().discoveries){if(d.claimed)continue;const [x,z]=worldToCell(d.pos);ctx.fillStyle=d.kind==='star'?'#ffd18a':d.kind==='spring'?'#82e0e9':'#d0abef';ctx.fillRect(x*scale-1.5,z*scale-1.5,3,3);}};
const discoveryCollision=rebuildCollision;
rebuildCollision=function(){if(G?.generatedBodies){G.generatedBodies=G.generatedBodies.filter(b=>!b.discovery);for(const d of G.economy?.settlement?.discoveries||[]){if(d.kind==='spring')continue;G.generatedBodies.push({x:d.pos.x,z:d.pos.z,y:d.pos.y,r:d.kind==='star'?.8:1.1,h:2,source:d,discovery:true});if(d.kind==='relic')for(let i=0;i<5;i++)G.generatedBodies.push({x:d.pos.x+Math.cos(i*1.256)*2,z:d.pos.z+Math.sin(i*1.256)*2,y:d.pos.y,r:.25,h:2,source:d,discovery:true});}}discoveryCollision();};

const residentModel=workerMesh;
workerMesh=function(job){const group=residentModel(job),tool=new THREE.Group();tool.name='workTool';tool.position.set(.35,.9,.2);const handle=new THREE.Mesh(new THREE.BoxGeometry(.08,.6,.08),new THREE.MeshStandardMaterial({color:0x947857})),head=new THREE.Mesh(new THREE.BoxGeometry(.32,.16,.15),new THREE.MeshStandardMaterial({color:0xaeb5b1,metalness:.45,roughness:.65}));head.position.y=.28;tool.add(handle,head);group.add(tool);return group;};
const settlementValidation=validateSave;
validateSave=function(save){settlementValidation(save);const p=save.state.player,validNumber=n=>Number.isFinite(n)&&n>=0&&n<=1e9;if(p.level!==undefined&&(!Number.isInteger(p.level)||p.level<1||p.level>10000))throw Error('Invalid character level');if(p.xp!==undefined&&!validNumber(p.xp))throw Error('Invalid character experience');for(const t of save.towers)if(t.construction&&(!validNumber(t.construction.done)||!validNumber(t.construction.total)||t.construction.total<=0))throw Error('Invalid construction progress');const colony=save.state.economy?.settlement;if(colony){if(!Array.isArray(colony.discoveries)||colony.discoveries.length>5000||colony.discoveries.some(d=>!['spring','star','relic'].includes(d.kind)||!Array.isArray(d.pos?.$v)||d.pos.$v.length!==3||!d.pos.$v.every(Number.isFinite)))throw Error('Invalid exploration landmarks');for(const w of save.state.economy.workers)if(!['laborer','knight','ranger','pyromancer'].includes(w.role)||!validNumber(w.hp)||!validNumber(w.maxHp))throw Error('Invalid settlement resident');}};
/* One placement point drives the cursor, click, keyboard and confirmation button. */
let confirmingBlueprint=false;
const placementAim=aimPoint;
aimPoint=function(){if(!G?.buildMode)return placementAim();if(mouseOverHud)return G.buildAim?.clone()||null;raycaster.setFromCamera({x:mouse.x,y:mouse.y},camera);const point=groundHit();G.buildAim=point?.clone()||null;return point;};
function inspectBlueprint(){const b=BUILDS[G.selected],hit=aimPoint();if(!hit)return {b,reason:'Point at terrain to choose a build location.'};const p=b.core?tilePoint(...worldToCell(hit)):buildPoint(...worldToCell(hit),hit),cell=worldToCell(p),side=b.wall?wallSide(...cell,hit):undefined;let reason=b.retired?'Train defenders at a training building.':b.core?coreReason(p):b.wall?wallPlacement(...cell,side):placementReason(b,p);if(!reason&&!b.core&&G.gold<buildCost(b))reason='Not enough gold: need '+buildCost(b)+', have '+G.gold+'.';if(!reason&&!b.core&&!canPay(DEFENSE_RECIPES[b.id]||{}))reason='Need materials: '+recipeText(DEFENSE_RECIPES[b.id]||{})+'.';return {b,p,cell,side,reason};}
const placementLog=log;
log=function(message){if(confirmingBlueprint&&G)G.buildFailure=message;placementLog(message);};
function confirmBlueprint(){if(!G?.buildMode||menuPaused||G.phase==='over')return;const plan=inspectBlueprint();if(plan.reason){G.buildSuccess=false;G.buildFeedback=plan.reason;G.buildFeedbackUntil=G.time+5;renderPlacementStatus();return false;}const before=G.towers.length+G.sites.length;G.buildFailure=null;confirmingBlueprint=true;try{place(plan.b,...plan.cell,plan.b.wall?plan.side:plan.p);}finally{confirmingBlueprint=false;}const success=G.towers.length+G.sites.length>before;G.buildSuccess=success;G.buildFeedback=success?(plan.b.core?'Portal gate placed.':plan.b.name+' blueprint placed. Laborers will build it.'):(G.buildFailure||'This position is blocked. Choose another spot.');G.buildFeedbackUntil=G.time+5;renderPlacementStatus();return success;}
const buildClick=clickWorld;
clickWorld=function(){if(G?.buildMode&&!G.workerOrder){confirmBlueprint();return;}return buildClick();};
function renderPlacementStatus(){if(!G?.buildMode||!document.getElementById('buildStatus'))return;const plan=inspectBlueprint(),feedback=G.time<(G.buildFeedbackUntil||0)?G.buildFeedback:null,text=feedback||plan.reason||'Ready: left-click the world, press F, or use Confirm blueprint.';$('buildStatus').textContent=text;$('buildStatus').classList.toggle('blocked',feedback?!G.buildSuccess:!!plan.reason);$('confirmBlueprint').disabled=!!plan.reason;$('confirmBlueprint').textContent=plan.b?.core?'Place portal gate · F':'Confirm blueprint · F';$('tip').textContent=plan.reason||'LMB / F confirms '+plan.b.name+' · '+(plan.b.core?'one portal kit':'laborers build it');if(G.cursor&&!plan.b.core)G.cursor.material.color.setHex(plan.reason?0xd86455:0x6bd5a8);}
const clearPlacementToggle=toggleBuildMode;
toggleBuildMode=function(){clearPlacementToggle();if(G){G.buildAim=null;G.buildFeedback=null;G.buildFeedbackUntil=0;}};
const confirmedPreview=previewWall;
previewWall=function(){confirmedPreview();renderPlacementStatus();};
const confirmInput=bindInput;
bindInput=function(){confirmInput();addEventListener('keydown',e=>{if(e.code!=='KeyF'||e.repeat||e.target?.closest?.('input,select,textarea')||!G?.buildMode||menuPaused||!$('draft').classList.contains('hidden'))return;e.preventDefault();confirmBlueprint();});};
const confirmInstall=installIntegration;
installIntegration=function(){confirmInstall();const footer=document.createElement('footer');footer.id='placementControls';footer.innerHTML='<p id="buildStatus" role="status" aria-live="polite">Point at terrain to choose a build location.</p><button id="confirmBlueprint">Confirm blueprint · F</button>'; $('constructionPanel').appendChild(footer);$('confirmBlueprint').onclick=confirmBlueprint;$('constructionPanel').querySelector('header p').textContent='Choose a blueprint, point at clear terrain, then left-click or press F. Laborers build confirmed plans.';};
